INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121067, 'spa', 'Desgajar ramas', 'Participio Piel que significa ''cortando'' o ''desgajando ramas,'' describiendo el juicio divino que abate al liderazgo orgulloso (Is 10:33). El verbo deriva del sustantivo para ''rama'' y representa una poda o tala enérgica. La acción de Dios contra la arrogancia asiria utiliza una imagen forestal: los árboles altos que representan a los altos oficiales serán derribados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121068, 'spa', 'Opiniones divididas', 'Opiniones divididas o lealtades escindidas en el compromiso religioso (1 R 18:21). Elías emplea este término metafóricamente junto con ''cojear,'' retratando el intento de Israel de adorar tanto a Yahvé como a Baal como quien camina con piernas desiguales. El sustantivo enfatiza la naturaleza bifurcada e inestable de mantener lealtades contradictorias, capturando la indecisión espiritual del pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121070, 'spa', 'Doble ánimo', 'Adjetivo que describe a personas de doble ánimo o tibias en su compromiso religioso (Sal 119:113). El salmista contrasta su amor por la ley de Dios con el rechazo hacia quienes mantienen lealtades divididas. El término enfatiza la escisión interior: querer servir a Dios mientras se conservan otras opciones abiertas. Señala una actitud de indecisión espiritual incompatible con la fidelidad al pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121072, 'spa', 'Bramar, ser azotado', 'Formas intransitivas y pasivas (Qal, Nifal, Pual) que significan agitarse tempestuosamente, bramar o ser sacudido por una tempestad. En Jonás 1:11 y 1:13 el mar «iba embraveciéndose» (סֹעֵר) cada vez con mayor violencia; en Isaías 54:11 Dios se dirige a Jerusalén como «azotada por tempestad» (סֹעֲרָה), una mujer golpeada por la aflicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121076, 'spa', 'Dispersar con torbellino', 'Forma causativa (Piel) que significa arrastrar, dispersar o esparcir como con un torbellino, usada transitivamente en contextos de juicio divino. En Oseas 13:3 los impíos son como tamo «arrastrado» (יְסֹעֲר) de la era por el viento; en Zacarías 7:14 Dios declara «los dispersé con torbellino entre las naciones».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121079, 'spa', 'Tempestad, torbellino', 'Tormenta violenta, tempestad o torbellino, empleado con frecuencia como metáfora del juicio divino. El uso profético predomina: el estribillo de Jeremías describe la ira de YHWH como «una tempestad arremolinada» que estalla sobre la cabeza de los impíos (Jer 23:19; 25:32; 30:23). En el Salmo 55:8 el salmista busca escapar «del viento impetuoso, de la tempestad», y el Salmo 83:15 invoca a Dios para que persiga a sus enemigos con su tempestad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121085, 'spa', 'Tormenta, tempestad, torbellino', 'Tormenta, tempestad, torbellino: vendaval violento o tempestad que predominantemente representa el poder divino en teofanía y juicio. La רוּחַ סְעָרָה (''viento tempestuoso'') introduce la visión del trono de Ezequiel (Ez 1:4) y la respuesta de YHWH a Job (Job 38:1; 40:6). Lleva a Elías al cielo (2 R 2:1, 11) y ejecuta el juicio profético (Is 29:6; Jer 23:19; 30:23; Zac 9:14). Solo en los Salmos 107 y 148 el término describe fenómenos climáticos naturales, y aun allí las tormentas permanecen bajo el dominio soberano de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121094, 'spa', 'Cuenco, vasija ritual', 'Cuenco o vasija utilizado en contextos rituales, del templo o domésticos. En Éxodo 12:22 los israelitas mojan hisopo en sangre recogida «en el lebrillo» (בַּסַּף) para marcar sus dinteles en la Pascua. Los inventarios del templo de 1 Reyes 7:50 y 2 Reyes 12:13 enumeran סִפּוֹת entre los utensilios sagrados, y 2 Samuel 17:28 incluye cuencos entre las provisiones llevadas a David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121099, 'spa', 'Copa de vértigo', 'Copa o cáliz empleado metafóricamente para el juicio divino en Zacarías 12:2, donde Dios hace de Jerusalén un «סַף רַעַל» (copa de vértigo) para las naciones circundantes. La imagen es la de un recipiente embriagador que hace tambalear a quienes beben de él, en paralelo con la «copa de la ira» de Isaías 51:17, 22 y Jeremías 25:15.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121100, 'spa', 'El umbral físico o dintel inferior en la base de un portal o entrada, principalm', 'El umbral físico o dintel inferior en la base de un portal o entrada, principalmente en la arquitectura del templo y del palacio. En la visión del templo de Ezequiel es un elemento estructural medido de las puertas del santuario (Ez 40:6-7; 41:16; 43:8). El título shomer hassaf (''guardián del umbral'') designa a funcionarios superiores del templo en el servicio sacerdotal y levítico (2 R 12:10; 22:4; 23:4; 25:18; Jer 35:4; 52:24). Isaías describe los umbrales temblando ante la voz de los serafines (Is 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121113, 'spa', 'Nombre propio', 'Nombre propio de un guerrero filisteo, uno de los descendientes de los gigantes (2 S 21:18). Fue muerto en batalla en Gob. El pasaje paralelo registra la variante ''Sipai,'' algo habitual en la transmisión de las crónicas. Estos encuentros con descendientes de gigantes formaron parte de las campañas militares de David para asegurar las fronteras de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121114, 'spa', 'Significado activo central en Qal', 'Significado activo central en Qal: lamentar, plañir o clamar en voz alta, normalmente por los muertos, pero también ante una catástrofe nacional o un desastre inminente. Este sentido abarca la gran mayoría de las ocurrencias. El español traduce consistentemente ''lamentar'', mientras que el francés usa ''pleurer'' (''llorar''), apuntando al carácter sonoro y demostrativo del duelo. Pasajes clave incluyen el duelo de Abraham por Sara (Gn 23:2) y el lamento de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121115, 'spa', 'Forma nifal (pasiva)', 'Forma nifal (pasiva): ser lamentado o llorado. En Jeremías 16:4 y 16:6, los que mueran ''no serán lamentados'': la construcción pasiva enfatiza no la acción del doliente, sino la ausencia de cualquier plañidero para el difunto. El español lo capta con la forma reflexiva ''serán llorados'', reflejando el desplazamiento del agente al paciente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121123, 'spa', 'El sustantivo derivado מִסְפֵּד, que designa una ceremonia de duelo, una ocasión', 'El sustantivo derivado מִסְפֵּד, que designa una ceremonia de duelo, una ocasión de lamentación o el sonido mismo del llanto. En Zacarías 12:10, el מִסְפֵּד se compara con el duelo en Hadad-Rimón, un topónimo asociado a un gran luto público. Miqueas 1:11 lo empareja con topónimos, sugiriendo un evento comunitario ritualizado más que un llanto espontáneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121124, 'spa', 'El participio sustantivado', 'El participio sustantivado: un plañidero, alguien que se golpea el pecho en lamentación profesional o ritual. Isaías 32:12 retrata a plañideros golpeándose el pecho por campos fértiles convertidos en desolación. Eclesiastés 12:5 sitúa a los סֹפְדִים en la calle como parte de su conmovedor retrato de la muerte, donde los plañideros profesionales rondando el mercado se convierten en imagen del fin de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121139, 'spa', 'Añadir, agregar', 'Añadir, agregar: raíz distinta (ספה II) que significa añadir, agregar o aumentar. En Números 32:14 se advierte a los rubenitas y gaditas que no ''añadan más'' a la ira de Dios. Isaías 30:1 condena a quienes ''añaden pecado sobre pecado,'' y Jeremías 7:21 dice con sarcasmo ''añadid vuestros holocaustos a vuestros sacrificios.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121140, 'spa', 'Barrer, destruir', 'Barrer, destruir: Qal activo que significa barrer o destruir, usado en juicios catastróficos o divinos sobre personas o lugares. La súplica de Abraham en Génesis 18:23 -- ''¿Barrerás al justo con el impío?'' -- es la instancia paradigmática. Isaías 7:20 lo extiende al afeitado: el Señor ''barrerá'' la barba con una navaja alquilada, metáfora de devastación completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121141, 'spa', 'Ser barrido, perecer', 'Ser barrido, perecer: pasivo Nifal que significa ser barrido, consumido o destruido, frecuentemente en el contexto de perecer junto con los culpables. Génesis 19:15 y 19:17 lo usan con urgencia cuando los ángeles advierten a Lot que huya ''para que no seas barrido en el castigo de la ciudad.'' En Números 16:26 se advierte a la congregación que se aparte de los rebeldes para no ser consumida con ellos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121152, 'spa', 'Ser alcanzado, atrapado', 'Ser alcanzado, atrapado: participio Nifal que significa ser alcanzado, atrapado o apresado, implicando persecución y captura más que mera destrucción. Isaías 13:15 dice ''todo el que sea alcanzado (הַנִּסְפֶּה) caerá a espada,'' describiendo a quienes son atrapados por el ejército conquistador. Este matiz de persecución y captura lo distingue del sentido general de ''ser barrido.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121153, 'spa', 'Amontonar, acumular', 'Amontonar, acumular: causativo Hifil que significa amontonar o acumular, específicamente apilar calamidades sobre alguien. Deuteronomio 32:23, en el Cántico de Moisés, tiene a Dios declarando ''Amontonaré (אַסְפֶּה) males sobre ellos.'' La imagen es de desastres apilados uno sobre otro, convirtiendo la imagen de barrido en una acción deliberada y medida de acumulación de juicios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121156, 'spa', 'Unirse o agregarse', 'Unirse, agregarse o asociarse con una persona, grupo o herencia, cubriendo un espectro desde la súplica personal desesperada hasta la incorporación a escala nacional. Una familia sacerdotal arruinada ruega ser agregada a cualquier oficio (1 Sam 2:36, Qal imperativo); David lamenta su exclusión de la herencia del Señor (1 Sam 26:19, Hitpael); extranjeros se unen a Israel (Is 14:1, Nifal).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121157, 'spa', 'Herir con sarna', 'Verbo Piel que significa ''herir con sarna o llagas,'' describiendo el juicio divino mediante enfermedad cutánea (Is 3:17). Dios afligirá a las mujeres orgullosas de Jerusalén con afecciones desfigurantes en el cuero cabelludo, transformando su belleza en vergüenza. La profecía utiliza la enfermedad física como manifestación de la corrupción moral, invirtiendo la vanidad que el profeta denuncia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121159, 'spa', 'Nombre propio', 'Nombre personal de un guerrero gigante filisteo (1 Cr 20:4), paralelo a Saf en 2 Samuel 21:18. La variación del nombre refleja diferencias típicas de transmisión textual entre Samuel y Crónicas. Fue uno de los descendientes de gigantes que se opusieron a las campañas militares de David. Las traducciones suelen transliterar o enmarcar el nombre, reconociendo su condición de nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121160, 'spa', 'Derramamientos o rebrotes', 'Término disputado en Job 14:19, posiblemente ''derramamientos'' (erosión hídrica) o ''rebrotes'' (vegetación espontánea). La mayoría de los intérpretes favorecen la imagen del agua: inundaciones que arrastran el suelo, como paralelo de cómo Dios destruye la esperanza humana. Su condición de hápax legómenon dificulta la certeza. Algunos estudiosos proponen enmendar el texto por completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121161, 'spa', 'Rebrote espontáneo', 'Designa el grano que brota de granos caídos accidentalmente, creciendo sin siembra deliberada. Levítico 25:5 y 11 legislan contra la recolección del rebrote del año sabático, mientras que 2 Reyes 19:29 e Isaías 37:30 prometen que este rebrote sustentará a Israel durante los años de crisis. Las traducciones multilingües lo expresan uniformemente como «lo que crece solo» o «rebrote espontáneo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121162, 'spa', 'Nave marítima', 'Embarcación de navegación marítima mencionada en la huida de Jonás de Dios (Jon 1:5). El profeta descendió a la bodega o cubierta inferior del barco. El término subraya la naturaleza construida y cerrada de la nave, revestida con tablones y cubierta. Esta elección léxica distingue los barcos grandes de las embarcaciones menores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121163, 'spa', 'Zafiro (piedra preciosa)', 'Piedra preciosa de color azul — casi con certeza lapislázuli en la mayoría de los contextos bíblicos — valorada por su profundo tono azur y empleada en descripciones teofánicas, vestiduras sacerdotales e imágenes poéticas de valor y belleza. El pavimento bajo los pies de Dios en el Sinaí es ''como zafiro'' (Éx 24:10), la visión del trono de Ezequiel incluye zafiro (Ez 1:26; 10:1) y la piedra ocupa un lugar en el pectoral del sumo sacerdote (Éx 28:18; 39:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121169, 'spa', 'Cubrir, artesonar', 'Cubrir, revestir o artesonar un edificio con madera, sentido arquitectónico central en formas activas y pasivas del Qal. Las cinco ocurrencias se relacionan con la construcción: el templo de Salomón (1 Re 6:9), su palacio (1 Re 7:3, 7), las salas de cedro de Joacim (Jer 22:14) y las casas artesonadas en tiempos de Hageo (Hag 1:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121172, 'spa', 'Reservar, guardar', 'Guardar, reservar o atesorar, extensión metafórica donde lo que está «cubierto» pasa a significar lo que se «guarda en reserva». En Dt 33:21 la porción del líder fue «reservada», aplicando la imagen de cubrir a la idea de algo apartado y protegido. Esta acepción se distingue claramente del sentido arquitectónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121174, 'spa', 'Techo interior', 'Término arquitectónico para el techo o cielo raso interior (1 R 6:15). El interior del templo fue completamente revestido con paneles de cedro, y este vocablo designa específicamente la superficie superior. El detalle enfatiza el recubrimiento integral de madera del espacio sagrado, desde el piso hasta el techo, expresando la dedicación total en la construcción del lugar santo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121175, 'spa', 'Estar en el umbral', 'Infinitivo hitpael que significa ''estar en el umbral'' o servir como portero (Sal 84:10). El salmista prefiere el servicio más humilde del templo —custodiar la entrada— antes que habitar con los malvados. La elección verbal enfatiza el posicionamiento voluntario y la presencia sostenida. El punto teológico valora cualquier proximidad a la presencia de Dios por encima de todo privilegio terrenal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121176, 'spa', 'Batir palmas, golpear', 'Significado primario en Qal: golpear, abofetear o batir palmas, ya sea las manos juntas con ira (Nm 24:10), con escarnio (Job 27:23; 34:37) o contra el muslo en duelo y arrepentimiento (Jer 31:19; Ez 21:17). Los transeúntes baten palmas sobre la ruina de Jerusalén (Lm 2:15). Job 34:26 extiende el sentido a Dios golpeando a los malvados como un castigo punitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121177, 'spa', 'Estrechar manos, aliarse', 'Hifil: estrechar o juntar las manos con otra persona como gesto de formar una alianza o pacto. En Isaías 2:6 se condena a Israel por darse la mano con extranjeros. Se trata de una acción social distinta del mero aplauso, que marca un acuerdo o pacto mediante el contacto físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121184, 'spa', 'Chapotear, vadear', 'Una extensión poco frecuente referida a chapotear o vadear en el agua, usada para las aguas crecientes en Ezequiel 47:2 que alcanzan la altura del tobillo y obligan a vadear. El vínculo semántico con el significado central es el movimiento repetido de golpeteo, aquí de las extremidades contra el agua en vez de las manos contra el cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121185, 'spa', 'Bastar, ser suficiente', 'Verbo que significa ''bastar'' o ''ser adecuado'', usado en la burla de Ben-hadad contra Samaria (1 R 20:10). El rey arameo se jacta de que sus fuerzas son tan numerosas que el polvo de la ciudad no alcanzará para dar un puñado a cada soldado. El verbo cuestiona la suficiencia, sugiriendo irónicamente la total inadecuación de Samaria ante una fuerza abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121186, 'spa', 'Escarnio o abundancia', 'Término disputado en Job 36:18, posiblemente ''escarnio'' (palmoteo burlón) o ''abundancia''. Elihú advierte a Job que no permita que la pasión lo incite a una respuesta despectiva ante la disciplina divina. Algunos lo vinculan con gestos de burla. Su condición de hápax y el contexto incierto hacen imposible una traducción segura; se ha propuesto enmienda textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121187, 'spa', 'Suficiencia o abundancia', 'Sustantivo que significa suficiencia o abundancia, referido a la prosperidad del impío (Job 20:22). Zofar describe la reversión irónica: en el apogeo de la abundancia, sobreviene el desastre. El término enfatiza provisión adecuada o excedente. El pasaje ilustra el tema de la literatura sapiencial de que la prosperidad de los malvados es ilusoria y temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121188, 'spa', 'relatar, narrar (Piel)', 'Piel: relatar, contar, narrar, declarar — la acepción más amplia con 64 ocurrencias, que abarca el significado central del tema intensivo: narración verbal y declaración. El siervo de Abraham ''contó'' todo lo sucedido (Gn 24:66), los hermanos de José ''relataron'' sus sueños (Gn 37:9-10) y el salmista se compromete a ''declarar'' las obras de Dios (Sal 9:1; 73:28; 78:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121193, 'spa', 'contar, numerar (Qal)', 'Qal: contar, numerar, calcular — 27 ocurrencias que cubren la enumeración básica en el tema simple. Dios dice a Abraham ''cuenta las estrellas, si las puedes contar'' (Gn 15:5), José dejó de contar el grano porque era incalculable (Gn 41:49) y el recuento censal de levitas y guerreros aparece en Números y Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121195, 'spa', 'ser contado (Nifal)', 'Nifal: ser contado, ser numerado — 8 ocurrencias en el tema pasivo, casi siempre en contextos de multitud incontable. A Agar se le dice que su descendencia ''no podrá ser contada por su multitud'' (Gn 16:10); igualmente la de Jacob (Gn 32:12), y los obreros importados de Salomón ''fueron contados'' en 153.600 (2 Cr 2:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121216, 'spa', 'ser relatado (Pual)', 'Pual: ser relatado, ser declarado — 5 ocurrencias en el pasivo del Piel, recibiendo la narración en vez de realizarla. ''¿Se le contará que yo quisiera hablar?'' (Job 37:20); ''lo que no se les había contado verán'' (Is 52:15); ''una posteridad le servirá; será contada al Señor por generación'' (Sal 22:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121250, 'spa', 'enumerar exhaustivamente (Piel)', 'Piel con fuerza de enumeración exhaustiva: contar minuciosamente, enumerar por completo — 3 ocurrencias donde la intensificación piel empuja a סָפַר de vuelta hacia su sentido de contar, pero con énfasis en la exhaustividad o en la imposibilidad declarada. ''¿Quién puede contar las nubes?'' (Job 38:37); ''puedo contar todos mis huesos'' (Sal 22:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121275, 'spa', 'Escriba, secretario real — un funcionario individual de la corte responsable de ', 'Escriba, secretario real — un funcionario individual de la corte responsable de documentos administrativos, correspondencia oficial y registros del estado. Es el sentido dominante con 48 ocurrencias, abarcando figuras como Sebna el secretario (2 R 18:18), Safán el escriba que lee la Torá a Josías (2 R 22:8) y Baruc hijo de Nerías que escribe al dictado de Jeremías (Jer 36:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121280, 'spa', 'Escribas, clase letrada — los escribas como clase profesional o gremio, usado en', 'Escribas, clase letrada — los escribas como clase profesional o gremio, usado en plural constructo para referirse a grupos organizados de funcionarios letrados. Las ''familias de escribas'' en Jabes (1 Cr 2:55) sugieren gremios hereditarios; los escribas levíticos que supervisan las obras del templo (2 Cr 34:13) forman un cuerpo profesional distinto; y los ''escribas del rey'' que redactan edictos reales (Est 3:12, 8:9) son un organismo burocrático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121288, 'spa', 'Libro o registro oficial', 'Documento escrito o registro oficial, empleado para archivos reales (Esd 4:15; 6:1) y el libro de la Ley de Moisés (Esd 6:18). En Daniel 7:10, el plural סִפְרִין designa libros celestiales de juicio abiertos ante el trono divino. El término es un préstamo arameo que refleja el vocabulario administrativo y legal del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121289, 'spa', 'Censo o enumeración', 'Término administrativo para censo o enumeración (2 Cr 2:17), específicamente de la fuerza laboral de Salomón. El sustantivo deriva del verbo ''contar'' y representa el recuento formal con fines organizativos. Crónicas emplea vocabulario burocrático acorde al extenso proyecto de construcción del templo. El término indica una evaluación sistemática de los recursos laborales disponibles entre los extranjeros residentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121290, 'spa', 'Topónimo en Arabia', 'Nombre de lugar que marca el límite oriental del territorio de los descendientes de Joctán (Gn 10:30). Tradicionalmente identificado con la antigua Ẓafār en el sur de Arabia, capital de los himyaritas, aunque la correspondencia fonológica es cuestionada. La forma direccional ''Sefarah'' (hacia Sefar) indica su condición de punto de referencia. La Septuaginta traduce Σωφηρα. Los detalles geográficos siguen siendo debatidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121291, 'spa', 'libro o rollo', 'Un libro o rollo: composición escrita de envergadura, ya sea histórica, legal, profética o litúrgica. ''El Libro del Pacto'' (Éx 24:7), ''el Libro de Jaser'' (Jos 10:13) y ''el Libro de la Ley'' (Dt 31:26) emplean esta acepción. Las 141 ocurrencias abarcan desde registros de guerra hasta profecías selladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121296, 'spa', 'carta o epístola', 'Una carta o epístola: comunicación escrita más breve enviada de una persona a otra. La carta fatídica de David a Joab ordenando la muerte de Urías (2 S 11:14-15), las cartas falsificadas por Jezabel selladas con el sello de Acab (1 R 21:8) y la correspondencia diplomática del exilio emplean esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121298, 'spa', 'documento o certificado oficial', 'Un documento oficial o certificado legal: instrumento formal con fuerza jurídica vinculante. La ''carta de divorcio'' (סֵפֶר כְּרִיתֻת, Dt 24:1, 3; Is 50:1; Jer 3:8) es el caso paradigmático, pero también abarca escrituras de propiedad (Jer 32:11-12) y decretos reales (Est 9:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121306, 'spa', 'tradición escribal, literatura', 'La literatura y el saber de una cultura extranjera, específicamente ''la escritura y la lengua de los caldeos'' (Dn 1:4, 17), donde סֵפֶר denota no un documento aislado sino toda una tradición escribal-erudita. Daniel y sus compañeros fueron instruidos en el סֵפֶר babilónico: el corpus literario cuneiforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121325, 'spa', 'Registro divino', 'Frase preposicional ''en tu libro'', parte de una oración pidiendo a Dios que registre las lágrimas del salmista (Sal 56:8). La metáfora retrata el registro divino: Dios lleva cuenta del sufrimiento humano. Algunos críticos textuales lo ven como adición de copistas, pero encaja con la teología bíblica de la memoria atenta de Dios. El motivo del ''libro'' aparece frecuentemente para el conocimiento y juicio divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121326, 'spa', 'Escriba, secretario', 'Escriba o secretario en la administración imperial persa, usado en las porciones arameas de Esdras tanto para funcionarios hostiles como para el propio Esdras. En Esd 4:8-23, Simsai redacta cartas oponiéndose a la reconstrucción de Jerusalén. En Esd 7:12, 21, el título se aplica a Esdras como escriba-erudito autorizado por Artajerjes para enseñar la ley de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121328, 'spa', 'Lugar de exilio', 'Lugar del exilio judío mencionado en el oráculo de restauración de Abdías (Abd 1:20). La mayoría de los estudiosos lo conectan con Sparda/Sardis en Asia Menor según inscripciones asirias, aunque también se han propuesto localizaciones en Media. La tradición judía posterior lo identificó con España, creando la designación ''sefardí''. La Septuaginta ofrece la lectura Ἐφραθά, una identificación diferente. El sitio albergaba una comunidad exiliada en espera de restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121329, 'spa', 'Cantidades innumerables', 'Sustantivo plural ''números'' en la confesión de que las obras justas de Dios exceden todo recuento (Sal 71:15). El salmista admite su incapacidad para enumerar las salvaciones y la justicia divinas. Algunas versiones leen ''escritos'' (vinculándolo a ''libro''), pero ''números'' se ajusta al contexto de incalculabilidad. La expresión subraya la fidelidad inagotable de Dios, cuyas misericordias superan cualquier intento de contabilización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121330, 'spa', 'Gentilicio de Sefarvaim', 'Gentilicio ''los sefarvitas'', pueblo de Sefarvaim reasentado en Samaria por Asiria (2 Re 17:31). Mantuvieron su culto nativo, que incluía sacrificios de niños a Adramélec y Anamélec. Sus prácticas religiosas contribuyeron al sistema de culto mixto que se desarrolló en la Samaria posterior a la conquista. El término sigue la formación gentilicia estándar del hebreo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121331, 'spa', 'Sefarvaim (topónimo)', 'Nombre propio de una ciudad mesopotámica conquistada por el imperio asirio, que aparece en forma dual (Sefarvaim), posiblemente reflejando sus dos barrios: Sippar de Shamash y Sippar de Anunitu, situados a ambos lados de un canal cerca de la actual Abu Habba, Irak. En 2 Reyes 17:24, 31 sus habitantes fueron deportados a Samaria tras la caída del reino del norte, trayendo consigo a sus dioses Adramélec y Anamélec.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121337, 'spa', 'El acto judicial de lapidación — apedrear a una persona o animal como ejecución ', 'El acto judicial de lapidación — apedrear a una persona o animal como ejecución comunitaria prescrita por la ley mosaica. Con 18 apariciones, es el sentido dominante, abarcando formas activas en Qal (''y lo apedrearon'', Jos 7:25; 1 R 21:13) y construcciones pasivas en Nifal/Pual (''será apedreado'', Éx 19:13). El español ''apedrear'' y el francés ''lapider'' convergen en este sentido punitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121340, 'spa', 'Quitar piedras de un campo o camino, preparando el terreno para el cultivo o el ', 'Quitar piedras de un campo o camino, preparando el terreno para el cultivo o el paso — un denominativo Piel que invierte las asociaciones violentas de la raíz. Solo 2 apariciones, ambas en Isaías: el dueño de la viña ''la desempedró'' antes de plantar (Is 5:2), y el mandato profético de ''quitar las piedras'' del camino del regreso (Is 62:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121345, 'spa', 'Arrojar o lanzar piedras contra alguien con hostilidad, distinto de la lapidació', 'Arrojar o lanzar piedras contra alguien con hostilidad, distinto de la lapidación judicial formal — un Piel intensivo que describe agresión personal. Se encuentra en 2 apariciones, ambas describiendo el ataque de Simei contra David durante la rebelión de Absalón: ''arrojaba piedras contra David'' y ''tirando piedras junto a él'' (2 S 16:6, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121354, 'spa', 'Hosquedad resentida', 'Ambos contextos muestran la reacción típica de Acab al no obtener lo que desea: retraimiento hosco en vez de aceptación sana. Tras la reprensión profética (20:43), vuelve malhumorado a casa. Cuando Nabot rechaza el trato (21:4-5), Acab se echa en cama como un niño haciendo berrinche. La pregunta de Jezabel identifica ese espíritu obstinado y enfurruñado como rasgo distintivo del rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121355, 'spa', 'Rebeldes o cardos', 'Término disputado en la narrativa vocacional de Ezequiel (Ez 2:6), interpretado como ''rebeldes/contumaces'' o bien ''cardos/espinos''. La raíz aramea sugiere contradicción o desafío, pero su emparejamiento con otro término vegetal ha favorecido la lectura ''cardos''. La Vulgata y parte de la tradición judía prefieren ''rebeldes'', mientras otros ven una metáfora de plantas espinosas. En cualquier caso, el pasaje describe una oposición feroz al ministerio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121357, 'spa', 'Rey asirio Sargón II', 'Nombre propio del rey asirio Sargón II (reinó 722–705 a.C.), mencionado en Isaías 20:1. Aunque aparece solo una vez en el texto bíblico, fue históricamente significativo como conquistador final de Samaria y padre de Senaquerib. Su nombre acadio Šarru-kēnu significa ''el rey es legítimo''. Las variantes de la Septuaginta muestran confusión textual, resuelta posteriormente gracias a las inscripciones asirias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121359, 'spa', 'Clan seredita', 'Gentilicio que designa al clan descendiente de Sered, de la tribu de Zabulón (Nm 26:26). El término aparece en las listas censales que organizaban las fuerzas combatientes de Israel por familias ancestrales. Estos marcadores genealógicos mantenían la estructura e identidad tribal durante la travesía por el desierto y servían de base para la posterior distribución de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121360, 'spa', 'Cisterna de Sirá', 'Topónimo que designa la ''cisterna de Sirá'', lugar cercano a Hebrón donde los hombres de Joab interceptaron a Abner (2 S 3:26). El sitio sirvió como punto de encuentro para la emboscada que resultó en el asesinato de Abner. La etimología posiblemente se conecta con ''apartarse'' o ''olla'', aunque el significado sigue siendo incierto. Las traducciones lo preservan uniformemente como nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121361, 'spa', 'Rebelión, apostasía', 'Rebelión, revuelta, apostasía o defección — el sentido dominante que cubre siete de las ocho ocurrencias. Denota un apartarse de Dios, de la lealtad al pacto o de la verdad moral. Deuteronomio 13:5 advierte contra quien «ha hablado rebelión contra el SEÑOR tu Dios», e Isaías lo emplea para la revuelta persistente de Judá (1:5; 31:6) y para un discurso que combina opresión con falsedad (59:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121364, 'spa', 'Cesación, retirada', 'Cesación, retirada o apartamiento — atestiguado únicamente en Isaías 14:6, donde el profeta describe una vara que golpeaba a los pueblos «sin cesar» (בִּלְתִּי סָרָה). Aquí la palabra conserva su sentido etimológico de ''apartarse'' sin la connotación moral de rebelión; simplemente significa detenerse o ceder, marcando un concepto temporal-aspectual: la ausencia de pausa en la opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121365, 'spa', 'Extenderse, colgar', 'Extenderse, desplegarse o colgar físicamente, describiendo la extensión de material u objetos orgánicos más allá de un límite. Éx 26:12-13 lo usa para las cortinas del tabernáculo que cuelgan sobre el armazón; Ez 17:6 para las ramas de una vid que se extienden; Ez 23:15 para turbantes que fluyen. El español ''colgará/colgantes'' confirma el sentido espacial y físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121368, 'spa', 'Desparramarse con exceso', 'Tenderse o desparramarse con exceso indolente, extensión figurada de ''extenderse'' aplicada a la postura humana y la laxitud moral. Am 6:4 denuncia a quienes se ''desparraman'' (סְרֻחִים) en sus lechos, y 6:7 advierte que los ''extendidos'' encabezarán el exilio. El español ''los extendidos'' retiene la imagen literal mientras el marco profético la convierte en un retrato de indiferencia decadente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121369, 'spa', 'Pudrirse, echarse a perder', 'Echarse a perder, pudrirse, corromperse: el sentido Nifal de deterioro. Jer 49:7 pregunta si la sabiduría de Edom ''se ha podrido'' (נִסְרְחָה), sugiriendo algo valioso que se descompuso. El español ''se ha podrido'' y el hindi ''sad gai'' lo traducen uniformemente como descomposición orgánica, indicando que la raíz de ''sobrepasar los límites'' puede significar madurar en exceso hasta la putrefacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121372, 'spa', 'Excedente o voladizo', 'Término arquitectónico para el excedente o voladizo de la cubierta del tabernáculo (Éx 26:12). La cortina de pelo de cabra se extendía más allá de las dimensiones de la estructura, creando un voladizo protector. El término enfatiza la porción sobrante que queda después de la cobertura principal. Este detalle revela un diseño cuidadoso para la protección contra las inclemencias del clima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121374, 'spa', 'Varón castrado, especialmente al servicio de una corte real o un harén', 'Varón castrado, especialmente al servicio de una corte real o un harén. La evidencia multilingüe es reveladora: el inglés oscila entre ''eunuch'' y ''officer'', mientras que el español usa consistentemente ''eunuco'' y el alemán ''Kämmerer'' (chambelán), reflejando la estrecha asociación entre la castración y el servicio en el harén. Este sentido predomina en las narraciones cortesanas de Reyes y Ester, donde los eunucos arrojaron a Jezabel y custodiaban a las reinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121378, 'spa', 'Alto funcionario real u oficial de la corte, usado como título de cargo sin impl', 'Alto funcionario real u oficial de la corte, usado como título de cargo sin implicar castración. Génesis aplica este vocablo a Potifar (Gn 37:36; 39:1), quien estaba casado y tenía un hogar propio, lo que hace improbable la lectura de eunuco. De igual modo, el copero mayor y el panadero mayor del Faraón son llamados sus סָרִיסִים (Gn 40:2,7). El español traduce estos casos como ''oficial de'' y el inglés como ''officer of'', distinguiéndolos claramente del sentido de eunuco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121395, 'spa', 'Comisionado imperial', 'Alto comisionado o prefecto imperial puesto al frente de los gobernadores provinciales, exclusivamente en Daniel 6:2-7, donde Darío nombra a tres de estos funcionarios para supervisar a los sátrapas. El término es un préstamo persa que refleja el vocabulario burocrático incorporado al arameo durante el período aqueménida, denotando autoridad administrativa de primer nivel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121396, 'spa', 'Seor, gobernante (ttulo filisteo) -- ttulo distintivo de cada uno de los cinco g', 'Seor, gobernante (ttulo filisteo) -- ttulo distintivo de cada uno de los cinco gobernantes de las ciudades-estado filisteas, que aparece siempre en plural (seranim). Se usa exclusivamente para el liderazgo poltico filisteo en Josu 13:3, Jueces 3:3 y 16:5-30, 1 Samuel 5-7 y 29, y 1 Crnicas 12:20. El trmino funciona como prstamo lingstico restringido a este nico contexto poltico, sin aplicarse jams a gobernantes israelitas ni de otras naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121405, 'spa', 'Eje de bronce', 'Ejes de bronce que sostenían las ruedas giratorias de las diez bases móviles del templo de Salomón (1 R 7:30). El término hebreo es infrecuente, apareciendo solo una vez, y las versiones antiguas tuvieron dificultades con él — el griego lo tradujo libremente como ''uniones''. El cognado arameo y el contexto del trabajo en bronce sugieren que se trataba de vocabulario técnico propio de la artesanía del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121406, 'spa', 'Ramas frondosas alegóricas', 'Las ramas exuberantes del árbol alegórico que representa al Egipto del Faraón (Ezequiel 31:5). Ezequiel describe cómo las ramas del gran cedro se multiplicaron «a causa de las muchas aguas», imagen del poder imperial que extiende su influencia. La estructura aramea del vocablo hebreo encaja con la tendencia de Ezequiel a adoptar préstamos mesopotámicos durante el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121407, 'spa', 'El que incinera', 'El encargado de quemar los cuerpos durante el juicio catastrófico descrito en Amós 6:10. En esta escena sombría, un pariente entra en la casa para sacar a los muertos «y quemarlos», probablemente porque las condiciones de peste o asedio impedían el entierro normal. Las traducciones multilingües captan el sentido participial: «el que lo quema», subrayando la implicación personal de un familiar en esta tarea trágica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121408, 'spa', 'Espino del desierto', 'La zarza o espino del desierto que cederá su lugar al mirto en Isaías 55:13, como parte de la visión profética donde la naturaleza misma celebra la redención. «En lugar de la ortiga crecerá el mirto»: la transformación de vegetación maldita en belleza fragante simboliza la reversión del exilio. Las versiones griega y latina la tradujeron como ortiga o planta urticante, subrayando su carácter indeseable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121409, 'spa', 'Ser obstinado, rebelde -- ser terco, obstinado o rebelde, denotando resistencia ', 'Ser obstinado, rebelde -- ser terco, obstinado o rebelde, denotando resistencia deliberada a la autoridad legtima, principalmente la soberana del pacto de Dios sobre Israel, pero tambin la autoridad paterna. Las formas participiales funcionan adjetivalmente en la mayora de las ocurrencias: el ''hijo terco y rebelde'' de Deuteronomio 21:18, Israel como ''novilla indmita'' en Oseas 4:16, e ''hijos rebeldes'' en Isaas 30:1. El Salmo 66:7 y 68:6 advierten contra la rebelin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121419, 'spa', 'Nombre propio: Setur', 'Setur hijo de Miguel, el espía que representó a Aser en el reconocimiento de Canaán (Números 13:13). Estuvo entre los diez que trajeron el informe temeroso sobre gigantes y ciudades fortificadas. El nombre aparece en transliteración griega como Σαθουρ o Θασουρ, reflejando variaciones en la pronunciación antigua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121420, 'spa', 'tapar, bloquear (Qal)', 'Significado activo central en Qal: tapar, bloquear o sellar físicamente. Se usa para la obstrucción militar de pozos (2 R 3:19, 25) y la estrategia de Ezequías de bloquear manantiales (2 Cr 32:3-4, 30). En Daniel 8:26 y 12:4 la misma forma se extiende al sellado de palabras proféticas: «cierra las palabras y sella el libro». El español «cegaron» y «cierra» reflejan tanto la aplicación física como la profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121421, 'spa', 'oculto, secreto', 'Extensión estativa o adjetival que significa «oculto, secreto, escondido». En Salmo 51:6 Dios desea la verdad «en lo oculto» (b''satum); en Ezequiel 28:3 ningún secreto está escondido del príncipe de Tiro. El paso del cierre físico a la ocultación epistemológica es natural. El español «secreto» y «lo oculto» traducen bien este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121427, 'spa', 'tapar (Piel intensivo)', 'Conjugación Piel intensiva: tapar de manera completa y deliberada. Génesis 26:15 y 18 describen a los filisteos cegando los pozos de Abraham tras su muerte, e Isaac reabriéndolos. La conjugación intensiva subraya lo deliberado y exhaustivo del acto. El español «los cegaron» capta esa totalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121428, 'spa', 'cerrado, sellado (Qal pasivo)', 'Participio pasivo Qal como estado resultativo: «cerrado, sellado». Daniel 12:9 declara que las palabras proféticas están «cerradas y selladas hasta el tiempo del fin». El español «cerradas» expresa con precisión el estado de clausura completado y perdurable: la visión permanece sellada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121429, 'spa', 'ser tapado (Nifal pasivo)', 'Forma Nifal pasiva: «ser tapado», indicando que algo es sellado o cerrado por un agente externo. Nehemías 4:7 informa que las brechas de la muralla de Jerusalén empezaban a cerrarse, lo que provocó la oposición enemiga. El español «a cerrarse» capta el sentido pasivo-reflexivo de la brecha que se va clausurando.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121432, 'spa', 'Bloquear la oración', 'El acto de Dios de excluir la oración en Lamentaciones 3:8: «Ha cerrado el paso a mi oración». En lo más profundo del sufrimiento de Jerusalén, el hablante se siente no solo ignorado sino activamente excluido, como si Dios hubiera levantado una barrera contra la súplica. El uso raro del verbo y su forma tardía sugieren que fue elegido por su sentido enfático de bloqueo y rechazo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121433, 'spa', 'Hifil', 'Hifil: esconder, ocultar (causativo) — ocultar a alguien o algo, incluyendo la expresión teológicamente crucial הֶסְתֵּר פָּנִים (''esconder el rostro''). Es el sentido dominante con 44 ocurrencias, abarcando desde Dios que esconde su rostro en juicio (Dt 31:17-18; Sal 13:1; Is 54:8) hasta Moisés que esconde su rostro ante la zarza ardiente (Éx 3:6) y seres humanos que ocultan a otros del peligro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121435, 'spa', 'Hitpael', 'Hitpael: esconderse deliberadamente — reflexivo-iterativo: esconderse de manera deliberada y persistente, enfatizando la intencionalidad en el ocultamiento. Solo 5 ocurrencias, pero cada una es memorable: los hombres de David escondiéndose en el desierto de Saúl (1 S 23:19; 26:1), y notablemente, Dios descrito como ''un Dios que se oculta'' (אֵל מִסְתַּתֵּר) en Is 45:15, una de las afirmaciones más profundas sobre la trascendencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121437, 'spa', 'Nifal', 'Nifal: esconderse, estar oculto — reflexivo/pasivo: esconderse, estar oculto, quedar encubierto. Con 31 ocurrencias, abarca tanto el auto-ocultamiento activo (Caín temiendo quedar ''oculto del rostro de Dios'', Gn 4:14; el prudente que ve el peligro y se esconde, Pr 27:12) como el estado pasivo de estar oculto (las faltas ocultas en Sal 19:12; las cosas secretas que pertenecen al SEÑOR en Dt 29:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121448, 'spa', 'Participio pasivo o uso estativo que denota un estado oculto o encubierto, disti', 'Participio pasivo o uso estativo que denota un estado oculto o encubierto, distinto del Nifal procesual. En Pr 27:5 el contraste entre ''reprensión abierta'' y ''amor oculto'' (אַהֲבָה מְסֻתֶּרֶת) emplea esta forma para describir la cualidad estática de estar encubierto, no el acto de encubrir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121463, 'spa', 'Imperativo o yusivo con sentido de dar cobijo o refugio — ''esconde'' como ocultam', 'Imperativo o yusivo con sentido de dar cobijo o refugio — ''esconde'' como ocultamiento protector del vulnerable. En Is 16:3 la orden es ''esconde a los desterrados'' del opresor. El matiz protector conecta סָתַר con el vocabulario del refugio divino y humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121496, 'spa', 'Lo oculto divino', 'Las realidades escondidas que solo Dios puede revelar, según Daniel 2:22, donde el profeta bendice a Dios por descubrir el sueño olvidado de Nabucodonosor. «Él revela lo profundo y lo oculto»: el arameo enfatiza que no se trata de lo meramente desconocido, sino de lo activamente encubierto, fuera del alcance de la sabiduría o adivinación humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121497, 'spa', 'Destrucción del templo', 'La destrucción del templo de Jerusalén por Nabucodonosor, descrita en Esdras 5:12: «destruyó esta casa». La narración aramea pone este verbo en boca de los ancianos judíos que explican a Tatnai por qué están reconstruyendo: los pecados de sus antepasados provocaron que Dios los entregara al rey babilonio, «quien destruyó esta casa y deportó al pueblo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121498, 'spa', 'Secreto o clandestinidad como cualidad abstracta, típicamente en la frase adverb', 'Secreto o clandestinidad como cualidad abstracta, típicamente en la frase adverbial בַּסֵּתֶר ''en secreto, secretamente''. Describe acciones ocultas o clandestinas: incitar a la idolatría en secreto (Dt 13:6), herir al prójimo a escondidas (Dt 27:24), comer el pan del secreto (Pr 9:17) y la formación del salmista ''en lo oculto'' en el vientre materno (Sal 139:15). El español ''en secreto/en oculto'' y el francés ''dans le secret'' captan fielmente este matiz abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121499, 'spa', 'Un escondite, refugio o cobertura protectora', 'Un escondite, refugio o cobertura protectora: un lugar concreto o semiconcreto de ocultamiento o amparo. Aparece frecuentemente en estado constructo: סֵתֶר פָּנֶיךָ ''el abrigo de tu presencia'' (Sal 31:20), סֵתֶר עֶלְיוֹן ''el abrigo del Altísimo'' (Sal 91:1), סֵתֶר רַעַם ''escondite del trueno'' (Sal 81:7). El español ''escondite'' y el francés ''abri'' confirman la lectura locativa concreta. En las teofanías, el escondite de Dios es su morada de nubes oscuras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121516, 'spa', 'Refugio ilusorio', 'El «refugio» que los dioses paganos impotentes no pueden ofrecer, según Deuteronomio 32:38 en el desafío satírico de Moisés. Tras describir cómo los enemigos de Israel confiaban en dioses que comían sus sacrificios y bebían sus libaciones, Moisés se burla: «¡Que se levanten y os ayuden, que sean vuestro refugio!». La construcción hebrea podría requerir enmendar el verbo al plural para concordar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121517, 'spa', 'Levita coatita', 'Sitri hijo de Uziel, levita mencionado en Éxodo 6:22 entre la familia extendida de Coat. Representa una de las líneas colaterales de la tribu sacerdotal, descendiente de Leví a través de Coat y Uziel. La genealogía establece la estructura del clan más amplio dentro del cual la familia de Aarón ostentaba el sumo sacerdocio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121518, 'spa', 'Sentido meteorológico primario', 'Sentido meteorológico primario: una nube o masa de nubes en el cielo. Abarca nubes de lluvia (1 R 18:44-45, donde el criado de Elías avista una nube pequeña como la palma de una mano), nubes teofánicas que sirven de carroza a Dios (Is 19:1, Sal 104:3) y usos figurados donde las nubes representan rapidez (Is 60:8) o fugacidad (Job 30:15). El francés ''nuées'' y el español ''nubes'' apuntan consistentemente a esta lectura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121526, 'spa', 'Forma intensificada que enfatiza nubes densas e impenetrables', 'Forma intensificada que enfatiza nubes densas e impenetrables: la masa de nubes que oculta la presencia de Dios. En 2 Samuel 22:12 y Salmo 18:11, Dios hace de la oscuridad espesa su dosel con ''densas nubes de los cielos''. Job 26:8 describe a Dios atando las aguas en sus nubes densas. El énfasis pasa de la meteorología al ocultamiento divino y al poder abrumador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121533, 'spa', 'Extensión abstracta a la espesura o densidad de una sustancia material, no a nub', 'Extensión abstracta a la espesura o densidad de una sustancia material, no a nubes propiamente dichas. Éxodo 19:9 habla de una ''nube densa'' (donde la densidad del medio, no el fenómeno meteorológico, es el foco), y 2 Crónicas 4:17 se refiere al barro denso de la llanura del Jordán usado para fundir objetos de bronce. La evidencia multilingüe se divide: unas versiones traducen ''nube'', otras ''espesura''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121536, 'spa', 'Extensión poco frecuente a vegetación densa', 'Extensión poco frecuente a vegetación densa: matorral o maleza tupida que ofrece ocultamiento. En Jeremías 4:29, la gente huye a los matorrales para esconderse de los ejércitos que se acercan. El hilo semántico que conecta masa de nubes y matorral es la opacidad y la cobertura: ambos bloquean la vista y ofrecen ocultamiento. Este uso aparece una sola vez, pero encaja con la idea central de la raíz: masa densa y encubridora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121537, 'spa', 'Elemento arquitectónico', 'La referencia en Reyes lo asocia con columnas en la arquitectura palatina, mientras que la visión de Ezequiel lo ubica en el pórtico del templo, «delante del pórtico, por fuera» (41:25). El plural «los doseles/umbrales» (41:26) sugiere múltiples instancias de este elemento. Las traducciones interlingüísticas reflejan la incertidumbre: se alternan entre «umbral», «dosel» y «viga», sin consenso definitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121538, 'spa', 'adorar, servir (a Dios)', 'Adorar o servir a una deidad en sentido religioso o pactual. Duplicado parcial de la acepción 1 que cubre tanto la adoración legítima de YHWH como el servicio idolátrico a dioses extranjeros, constituyendo el verbo clave de fidelidad y apostasía a lo largo de la literatura deuteronomista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121546, 'spa', 'trabajar, laborar', 'Trabajar o laborar en sentido productivo general, sin objeto personal ni divino. Cubre el marco del mandamiento sabático (''seis días trabajarás'', Éx 20:9; 34:21), el trabajo forzado en Egipto (Éx 1:14; 5:18) y la condición de los trabajadores obligados (Lv 25:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121548, 'spa', 'servir a una persona', 'Servir o ministrar a un amo, señor o rey humano en capacidad personal. Jacob sirve a Labán (Gn 29:18, 25, 27), vasallos sirven a soberanos (Gn 14:4) y a Esaú se le dice que servirá a su hermano (Gn 27:40): todo servicio relacional y jerárquico sin componente cultual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121549, 'spa', 'siervo, obrero (participio)', 'Participio activo Qal usado como sustantivo: siervo, adorador u obrero como persona. Incluye a Isacar convertido en ''siervo de tributo'' (Gn 49:15), trabajadores levíticos contados para el servicio del tabernáculo (Nm 4:37, 41) y cananeos sometidos a cuadrillas de trabajo (Jos 16:10; 1 R 9:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121581, 'spa', 'labrar, cultivar (tierra)', 'Labrar, cultivar o trabajar la tierra agrícola. Primordial en Génesis: nadie para labrar la tierra (Gn 2:5), Adán puesto en Edén ''para labrarla'' (Gn 2:15), luego expulsado ''a labrar la tierra'' de la que fue tomado (Gn 3:23). Caín como ''labrador de la tierra'' (Gn 4:2, 12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121592, 'spa', 'esclavizar, someter (Hifil)', 'Causativo hifil: esclavizar, forzar a servir, someter a trabajo forzado. Central en el paradigma del Éxodo: Dios dice a Abraham que su descendencia será esclavizada (Gn 15:14), Egipto hace servir a Israel con dureza (Éx 1:13; 6:5) y reyes posteriores conscriptan trabajadores (2 Cr 2:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121604, 'spa', 'ser labrado, ser cultivado (Nifal)', 'Nifal pasivo de la acepción agrícola: tierra siendo labrada o cultivada. Poco frecuente (4 veces), aparece en la ley del asesinato no resuelto donde se lleva una becerra a tierra no labrada (Dt 21:4), la observación de Qohélet sobre la tierra (Ec 5:9) y la promesa de restauración de Ezequiel de que la tierra desolada ''será labrada''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121658, 'spa', 'servidumbre padecida', 'Uso difícil, casi hapax, en Is 14:3, donde el contexto habla del descanso tras el duro servicio. Funciona como referencia resumida a la experiencia de esclavitud, marcando el cese de la servidumbre forzada en la sátira contra el rey de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121698, 'spa', 'Ser hecho, ser realizado, ser llevado a cabo — el Hitpael pasivo en 9 aparicione', 'Ser hecho, ser realizado, ser llevado a cabo — el Hitpael pasivo en 9 apariciones, concentrado en la correspondencia imperial de Esdras. Los funcionarios persas informan que la obra del templo ''se hace con diligencia'' (Esd 5:8), los decretos reales especifican lo que ''se hará'' a los transgresores (Esd 6:11-12), y Artajerjes ordena que todo lo que Esdras solicite ''sea hecho'' con exactitud (Esd 7:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121699, 'spa', 'Hacer, realizar, llevar a cabo una acción — el sentido activo Qal de propósito g', 'Hacer, realizar, llevar a cabo una acción — el sentido activo Qal de propósito general en 16 apariciones. Es el significado predeterminado de ''hacer'' en contextos administrativos y narrativos: a los funcionarios se les indica qué ''hacer'' con los fondos del templo (Esd 6:8; 7:18), los rebeldes en Jerusalén históricamente ''hicieron'' sedición (Esd 4:15), y Nabucodonosor reconoce que Dios ''hace'' según su voluntad (Dn 4:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121708, 'spa', 'Celebrar u observar una festividad — una única aparición idiomática en Esdras 6', 'Celebrar u observar una festividad — una única aparición idiomática en Esdras 6:16, donde los exiliados que regresaron ''celebraron'' la dedicación del templo reconstruido. Aquí avad toma una festividad o ceremonia como objeto directo, extendiendo ''hacer/realizar'' hacia la observancia ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121713, 'spa', 'Hacer, construir, producir un objeto físico — 2 apariciones donde avad significa', 'Hacer, construir, producir un objeto físico — 2 apariciones donde avad significa ''fabricar'' o ''crear'' en lugar del genérico ''hacer''. En Daniel 3:15, Nabucodonosor desafía a los tres hombres respecto a la imagen que ''he hecho''; en Jeremías 10:11 (el único versículo arameo en Jeremías), los dioses que no ''hicieron'' cielos y tierra perecerán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121719, 'spa', 'Siervo, esclavo', 'Sustantivo arameo para siervo o esclavo, empleado en contextos tanto reales como teológicos. En el lenguaje diplomático, los oficiales se identifican como siervos del rey (Esd 4:11, ''tus siervos''; Dn 2:4, 7). En contextos confesionales y narrativos, designa a los fieles siervos de Dios: Daniel es ''siervo del Dios viviente'' (Dn 6:21), y los tres compañeros son reconocidos como siervos de Dios que confiaron en Él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121725, 'spa', 'Siervo, servidor, súbdito', 'Un siervo, servidor, funcionario o súbdito: cualquier persona que sirve a otra en ámbito doméstico, cortesano, militar o político, incluida la autorreferencia deferencial ''tu siervo'' significando ''yo/mí''. Este sentido abrumadoramente dominante (723 apariciones) abarca los siervos de Faraón (Gn 20:8; Éx 7:10), oficiales reales y la ubicua fórmula de cortesía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121740, 'spa', 'Esclavo, siervo forzado', 'Un esclavo o siervo en servidumbre: persona poseída como propiedad, comprada con dinero, nacida en la casa o sometida a servicio involuntario bajo la ley bíblica. Con 63 apariciones, este sentido emerge en los códigos legales (Éx 21:2-6, la ley del esclavo hebreo; Lv 25:39-46) e inventarios económicos que enumeran esclavos junto al ganado (Gn 12:16; 24:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121761, 'spa', 'Siervo de Dios', 'El título honorífico ''siervo de Dios/del SEÑOR'', aplicado a patriarcas, profetas y reyes distinguidos en relación pactal especial con YHWH. Solo 17 apariciones en esta formulación distintiva, pero cada una conlleva inmenso peso teológico: ''Mi siervo Abraham'' (Gn 26:24), ''Mi siervo Moisés'' (Nm 12:8), ''Mi siervo David'' (2 S 3:18; 7:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121808, 'spa', 'Ebed (nombre propio)', 'Nombre propio masculino que significa «siervo (de Dios)», aplicado a dos individuos distintos. El más destacado es el padre de Gaal, cuyo hijo convocó a los ciudadanos de Siquem contra Abimelec (Jue 9:26-35). El segundo Ebed aparece como cabeza de familia que regresó del exilio con Esdras (Esd 8:6). Las traducciones transliteran el nombre en lugar de traducirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121810, 'spa', 'Obras bajo Dios', 'Las obras de los justos y sabios en Eclesiastés 9:1, donde el Predicador observa que, pese al esfuerzo y la sabiduría humana, los resultados finales permanecen en la mano de Dios. «Todo esto examiné en mi corazón: los justos y los sabios y sus obras están en la mano de Dios», pero si amor u odio les espera, nadie lo sabe. La forma aramea refleja el carácter lingüístico tardío del libro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121812, 'spa', 'El nombre propio Obed-Edom (hebreo oved edom, ''siervo de Edom''), que identifica ', 'El nombre propio Obed-Edom (hebreo oved edom, ''siervo de Edom''), que identifica al geteo que albergó el Arca y fue bendecido (2 S 6:10-12; 1 Cr 13:13-14), a porteros y músicos levíticos en el servicio del templo (1 Cr 15-16; 26:4-15) y a un custodio del tesoro del templo (2 Cr 25:24). Si se trata de un solo individuo o de varios sigue siendo debatido. Las traducciones conservan uniformemente la forma compuesta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121819, 'spa', 'Padre de Selemías', 'Avdeel, padre de Selemías, mencionado en Jeremías 36:26 cuando el rey Joacim ordenó a su hijo y a otros dos funcionarios apresar a Jeremías y a su escriba. El nombre sigue el patrón semítico generalizado de declarar al hijo ''siervo de Dios'', con paralelos en inscripciones fenicias, nabateas y sabeas. A pesar de la misión persecutoria de su hijo, el Señor ''los escondió''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121820, 'spa', 'servicio cultual del tabernáculo', 'Servicio cultual del tabernáculo o del templo (~93 veces): con diferencia la acepción dominante. Cubre los deberes levíticos de transportar, montar y mantener el santuario (Nm 3:7-8; 4:4-33), el servicio de adoración y sacrificio (1 Cr 28:13-14) y el mantenimiento del templo (2 Cr 34:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121822, 'spa', 'servicio o ministerio general', 'Servicio o ministerio general (~29 veces): deberes no cultuales prestados a una persona, gobernante o comunidad. Incluye la observancia de la Pascua como un ''servicio'' (Éx 12:25-26), la administración real (1 Cr 26:30) y roles ministeriales asignados. Ocupa un registro intermedio entre lo sagrado y lo secular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121834, 'spa', 'trabajo o labor', 'Trabajo o labor (~18 veces): esfuerzo físico productivo, especialmente agrícola o de construcción. Sal 104:23 lo emplea para la persona que sale ''a su trabajo'' en los campos; 1 Cr 27:26 especifica labor agrícola. Las narrativas del Éxodo describen la עֲבֹדָה de Israel en Egipto inicialmente en este sentido neutro de trabajo duro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121841, 'spa', 'esclavitud o servidumbre', 'Esclavitud o servidumbre (~5 veces): trabajo forzado impuesto a un pueblo subyugado, con connotaciones de opresión y deshumanización. Éx 6:6 y 6:9 lo emplean para la aplastante servidumbre de Egipto de la cual Dios libera a Israel; 1 R 12:4 registra la queja de Jeroboam sobre el pesado yugo de Salomón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121871, 'spa', 'Abdón (nombre propio)', 'El nombre propio Abdón, que identifica a múltiples individuos y una localidad: (a) un juez menor de Piratón que gobernó Israel ocho años, conocido por su numerosa familia de setenta descendientes montados en asnos (Jue 12:13, 15); (b) un benjaminita en la genealogía de Saúl (1 Cr 8:23; 8:30; 9:36); (c) Abdón hijo de Micaías, enviado por el rey Josías a consultar a la profetisa Hulda (2 Cr 34:20); (d) una ciudad levítica en Aser (Jos 21:30; 1 Cr 6:74).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121873, 'spa', 'Servidumbre forzada', 'Los dos usos de Esdras (9:8-9) reconocen la realidad postexílica: aunque la comunidad regresó a la tierra, permanecía bajo autoridad persa, una forma de servidumbre más leve que la de Egipto o Babilonia. La fidelidad de Dios se extiende incluso dentro de este sometimiento, concediendo «alivio» pese a la sujeción. La referencia de Nehemías (9:17) evoca la esclavitud egipcia en contraste con la gracia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121874, 'spa', 'Nombre propio', 'Nombre personal atestiguado tres veces en textos postexílicos y genealógicos. Aparece en genealogías levíticas (1 Crónicas 6, 2 Crónicas 29) y en el relato de la reforma de Esdras. Las traducciones al español e inglés conservan el nombre como ''Abdi'', mientras que otras lenguas muestran variación al manejar el nombre propio, reflejando distintas filosofías de traducción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121875, 'spa', 'Gadita ancestral', 'Abdiel el gadita, registrado en 1 Crónicas 5:15 dentro de la genealogía de la tribu de Gad asentada al este del Jordán. El nombre sigue el extendido patrón semítico de declarar al hijo ''siervo de Dios'', con paralelos en inscripciones fenicias, nabateas y sabeas. Las versiones griegas lo transliteran como Abdeel o Abdiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121876, 'spa', 'Abdas (nombre propio) -- nombre personal hebreo Ovadyahu / Ovadyah (''siervo de Y', 'Abdas (nombre propio) -- nombre personal hebreo Ovadyahu / Ovadyah (''siervo de YHWH''), que identifica a numerosos individuos, incluyendo al mayordomo temeroso de Dios del palacio de Acab que escondi a cien profetas (1 Re 18:3-16), al profeta autor del libro ms breve de la Biblia hebrea (Abd 1), a un descendiente davdico (1 Cr 3:21), jefes de Isacar y Zabuln (1 Cr 7:3; 27:19), y varios levitas y funcionarios en Crnicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121884, 'spa', 'Ebed-Melec (nombre propio)', 'Oficial cusita (etíope) al servicio del rey Sedequías de Judá, cuyo nombre significa ''siervo del rey.'' Intervino para salvar a Jeremías de la muerte en una cisterna fangosa, pidiendo audiencia al rey y sacando personalmente al profeta con trapos y cuerdas (Jer 38:7-13). Dios recompensó su valentía con un oráculo individual de liberación durante la caída de Jerusalén (Jer 39:15-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121888, 'spa', 'Abed-nego (nombre propio)', 'Nombre babilónico dado a Azarías de Judá en la corte babilónica, que probablemente significa «siervo de Nebo». Uno de los tres compañeros de Daniel que se niegan a adorar la estatua de oro y son arrojados al horno de fuego ardiente, pero son preservados milagrosamente (Dn 3:12-30). Todas las apariciones se encuentran en las secciones arameas de Daniel: su nombramiento administrativo (Dn 2:49), la acusación ante Nabucodonosor (Dn 3:12-14) y su liberación sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121889, 'spa', 'Grosor y torpeza', 'El verbo aparece en contextos de comparación (el dedo de Roboam frente a la cintura de Salomón) y de diagnóstico espiritual (la rebelión de Israel causada por la prosperidad). Las traducciones captan la dimensión física (''grueso''), pero el sentido metafórico de insensibilidad espiritual requiere matices adicionales. El pasaje de Deuteronomio es especialmente llamativo por su transición de lo físico a lo moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121890, 'spa', 'Prenda o garantía', 'Objeto entregado como garantía de una deuda o préstamo. Las cuatro apariciones se encuentran en Deuteronomio 24:10-13, un texto legal que regula las prácticas de toma de prendas. La ley prohíbe la incautación forzosa, ordena que el acreedor espere fuera mientras el deudor saca la prenda, y exige la devolución del manto empeñado por un pobre al caer la noche.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121891, 'spa', 'Por causa de, a causa de, en atención a — causal o benefactivo, indicando la raz', 'Por causa de, a causa de, en atención a — causal o benefactivo, indicando la razón, el fundamento o la persona que motiva una acción. Cubre 35 de 49 ocurrencias. La tierra fue maldecida ''por causa de ti'' (Gn 3:17), y la bendición divina se canaliza ''por amor de'' figuras clave (Gn 18:26, 29; 26:24; 2 S 5:12; 7:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121892, 'spa', 'Para que, a fin de que — final o télico, introduciendo una cláusula de propósito', 'Para que, a fin de que — final o télico, introduciendo una cláusula de propósito o resultado deseado. Se encuentra en 14 pasajes, especialmente en discurso directo donde un personaje explica su objetivo. Rebeca dice a Jacob que prepare comida ''para que'' Isaac lo bendiga (Gn 27:4, 10, 19, 31); Abraham aparta siete corderas ''a fin de que'' sirvan como testimonio (Gn 21:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121912, 'spa', 'Tomar en prenda', 'Formas Qal que significan «tomar una prenda» o «pedir prestado con garantía», presentando la perspectiva del deudor o del que toma la prenda. En Dt 24:10 se prohíbe al acreedor entrar en la casa del prójimo para tomar su prenda, mientras que Dt 15:6 contrasta el prestar (Hifil) con el tomar prestado (Qal) en la misma promesa de bendición nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121913, 'spa', 'Prestar con prenda', 'Formas causativas Hifil que significan «prestar (con prenda)», representando la perspectiva del acreedor en la transacción. Dt 15:6 promete que el Israel obediente prestará a muchas naciones, y Dt 15:8 ordena prestar generosamente al hermano pobre: «ciertamente le prestarás». Las glosas en español e idiomas afines confirman consistentemente el sentido de otorgar un préstamo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121918, 'spa', 'Prendas opresivas', 'La pesada carga de prendas que el opresor malvado acumula sobre sí mismo en Habacuc 2:6. El canto de burla exclama: ''¡Ay del que se carga de prendas gravosas!'' La forma intensiva subraya no solo la deuda, sino el peso aplastante y opresivo de múltiples obligaciones arrancadas por la fuerza a las víctimas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121919, 'spa', 'Grosor de objetos', 'Designa el grosor, espesor o anchura de objetos sólidos. Aparece en relatos de construcción del templo (1 Reyes 7:26, 2 Crónicas 4:5: grosor del mar de bronce), descripciones proféticas (Jeremías 52:21: espesor de columnas) y metáfora poética (Job 15:26: protuberancias gruesas de escudos que representan orgullo obstinado). Las glosas multilingües lo traducen como «grosor/espesor/thickness».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121920, 'spa', 'Obra, servicio, administración', 'Obra, servicio o deber administrativo en un contexto oficial o sagrado. En Esdras, el término designa la construcción física del templo (Esdras 4:24; 5:8; 6:7) y el servicio ritual organizado ante Dios (Esdras 6:18). En Daniel, se refiere a la administración provincial, los asuntos de estado delegados por el rey (Dan 2:49; 3:12). Las traducciones multilingües — español ''servicio/obra'', francés ''travail/service'' — confirman uniformemente este rango.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121925, 'spa', 'pasar, atravesar (Qal)', 'La acepción Qal más frecuente: pasar por, pasar a través o pasar a lo largo de un lugar en tránsito, sin énfasis en cruzar un límite. Abraham ''pasó por la tierra'' reconociéndola (Gn 12:6), la antorcha humeante ''pasó entre'' las piezas (Gn 15:17), viajeros pasan de largo por un camino (Jue 19:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121931, 'spa', 'cruzar, atravesar (Qal)', 'Acepción Qal que enfatiza el cruce de un límite físico como un río, mar, frontera o umbral. Israel ''cruzó'' el Jordán en seco (Jos 3-4), Abraham ''cruzó'' el Éufrates para entrar en Canaán, ejércitos vadean ríos para invadir (2 S 17:22) y viajeros entran o salen de territorios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121936, 'spa', 'pasar, cesar (Qal)', 'Acepción Qal que describe el paso temporal, la cesación o la desaparición: el tiempo, las estaciones, la ira o la vida que se extinguen. Los días de duelo ''pasaron'' (Gn 50:4), la siega ''ha pasado'' (Jer 8:20) y la ira de Dios ''pasa'' cuando el juicio amaina (Job 14:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121939, 'spa', 'hacer cruzar (Hifil)', 'Causativo hifil: hacer cruzar, conducir al otro lado o llevar más allá de un límite físico. Dios ''hizo pasar'' un viento sobre la tierra para secar el diluvio (Gn 8:1), se ''hizo cruzar'' a Israel el Jordán (2 S 19:18), y Moisés ordena ''hacer pasar por el fuego'' como dedicación o rito pagano (Éx 13:12; Lv 18:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121957, 'spa', 'transgredir, violar (Qal)', 'Acepción Qal especializada que denota transgresión moral o legal: cruzar el límite del pacto, mandamiento o juramento. Moisés advierte ''¿por qué transgredís el mandamiento del Señor?'' (Nm 14:41), Balaam rehúsa ''traspasar la palabra del Señor'' (Nm 22:18), y Josué pone piedras como testigo ''para que no transgredan'' (Jos 24:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121977, 'spa', 'quitar, remover (Hifil)', 'Causativo hifil que significa quitar, retirar o apartar: levantar algo o transferirlo a otro lugar. José ''trasladó'' a los egipcios a las ciudades (Gn 47:21), David ''se quitó'' la armadura de Saúl (1 S 17:39), Dios ''quita'' la iniquidad (2 S 12:13) y los ídolos son ''retirados'' (Gn 35:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122020, 'spa', 'desbordar, fluir (Qal)', 'Acepción Qal aplicada a líquidos: desbordarse, fluir o derramarse. La amada describe manos ''que fluyen mirra'' (Cnt 5:5), labios ''que destilan mirra'' (5:13) e Isaías advierte que el río crecido ''se desbordará'' (Is 23:10). Extensión del sentido básico de ''pasar'' al agua que rebasa sus orillas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122029, 'spa', 'transferir, traspasar (Hifil)', 'Causativo hifil: transferir, traspasar o transmitir propiedad, posesión o herencia de una parte a otra. Las hijas de Zelofehad reciben el dictamen de que la herencia de su padre ''pasará a ellas'' (Nm 27:7-8) y Ester recibe el anillo de Amán ''traspasado'' a Mardoqueo (Est 8:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122041, 'spa', 'proclamar, difundir (Hifil)', 'Causativo hifil: hacer pasar una voz, decreto o sonido por un campamento o tierra; emitir proclamas, tocar trompetas, enviar órdenes. Moisés ''hizo pasar proclama por el campamento'' (Éx 36:6), la trompeta del jubileo ''resonará por'' toda la tierra (Lv 25:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122142, 'spa', 'fecundar, cubrir (Piel)', 'Acepción Piel intensiva poco frecuente que significa fecundar, hacer concebir. Job observa que ''su toro fecunda sin fallo'' (21:10). Este sentido puede implicar hacer pasar la simiente al vientre, una extensión agrícola-reproductiva especializada del movimiento de tránsito básico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122239, 'spa', 'Enfurecerse, encolerizarse', 'El Hitpael reflexivo que expresa una furia intensa y autogenerada. Se usa casi siempre de la ira de Dios en los Salmos y Deuteronomio: Salmo 78:21, 59, 62 y 89:38 retratan a Yahvé ''encolerizándose'' ante Israel que quebranta el pacto. En Proverbios 14:16 y 20:2 el término se extiende a la ira humana descontrolada, con la cualidad reflexiva e intensificadora del Hitpael.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122246, 'spa', 'Pasar de largo', 'Una única aparición en Proverbios 26:17 donde la forma funciona como participio Qal de la raíz principal עָבַר (''pasar''), describiendo a alguien que ''pasa de largo'' y se entromete en una disputa ajena. Se trata de un movimiento simple, distinto del sentido de furia del Hitpael, aunque BDB lo agrupa aquí por la coincidencia formal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122247, 'spa', 'allende, mas alla', 'La region del otro lado, usada exclusivamente en la frase administrativa aramea עֲבַר נַהֲרָה (''Allende el Rio'') para designar la satrapia persa al oeste del Eufrates. Aparece a lo largo de la correspondencia de Esdras relativa a la reconstruccion del templo: cartas dirigidas a y desde los gobernadores provinciales (Esd 4:10-11, 16-17, 20; 5:3, 6; 6:6, 8, 13) y decretos reales que autorizan apoyo desde la satrapia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122249, 'spa', 'más allá, región al otro lado — La región que se encuentra al otro lado o más al', 'más allá, región al otro lado — La región que se encuentra al otro lado o más allá de un accidente geográfico, especialmente un río, mar o frontera (73 ocurrencias). Este sentido dominante aparece con preposiciones para indicar ubicación (בְּעֵבֶר, ''al otro lado de'') o movimiento (מֵעֵבֶר, ''desde más allá''). La expresión עֵבֶר הַנָּהָר (''más allá del Río'', es decir, el Éufrates) funciona como designación geográfica semipropia en Josué 24:2-3.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122256, 'spa', 'lado, dirección, flanco — Un lado, flanco o cara direccional de un objeto o pers', 'lado, dirección, flanco — Un lado, flanco o cara direccional de un objeto o persona, sin referencia a cruzar un límite (15 ocurrencias). Se usa para los lados del candelabro de oro (Éx 25:37), los bordes de las vestiduras sacerdotales (Éx 28:26; 39:19) o la cara de un precipicio (1 S 14:1, 4). Los traductores reconocen aquí un sentido espacial distinto al de ''más allá''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122267, 'spa', 'lados, bordes (plural) — Los lados o bordes de un objeto en referencia plural o ', 'lados, bordes (plural) — Los lados o bordes de un objeto en referencia plural o dual, generalmente con sufijos posesivos: ''sus lados'', ''sus costados'' (4 ocurrencias). Éxodo 32:15 describe tablas escritas en ''sus dos lados'' (מִשְּׁנֵי עֶבְרֵיהֶם), y 1 Reyes 4:24 habla de dominio sobre ''toda la región de este lado'' usando una forma pluralizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122280, 'spa', 'Eber (nombre propio)', 'Nombre propio עֵבֶר, llevado principalmente por el patriarca semita registrado en Genesis 10-11 y 1 Cronicas 1 como ancestro de las lineas hebrea y arabica. El nombre probablemente deriva de la raiz ע-ב-ר (''cruzar''), conectandose etimologicamente con עִבְרִי (''hebreo''). El titulo de Sem como ''padre de todos los hijos de Eber'' (Gn 10:21) confiere al nombre una dimension corporativa y etnografica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122285, 'spa', 'Ira intensa, furor o rabia — abrumadoramente la cólera divina desatada en juicio', 'Ira intensa, furor o rabia — abrumadoramente la cólera divina desatada en juicio, aunque también aplicada a la furia humana (Gn 49:7; Pr 14:35). Este sentido dominante (30 ocurrencias) abarca ''el día de la ira de YHWH'' (Sof 1:15, 18), el furor ardiente enviado contra Egipto (Sal 78:49) y la vara de la furia de Dios blandida contra las naciones (Is 10:6; 14:6). El español ''ira/furor'', el francés ''colère/fureur'' y el alemán ''Zorn/Grimm'' convergen en la noción de cólera intensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122296, 'spa', 'Arrogancia o presunción insolente', 'Arrogancia o presunción insolente: un desbordamiento de orgullo que transgrede los límites debidos. Solo dos ocurrencias claras, pero ambas son instructivas: Proverbios 21:24 identifica al burlador como quien actúa ''en el desbordamiento de insolencia'' (עֶבְרַת זָדוֹן), y Jeremías 48:30 denuncia la עֶבְרָה de Moab junto con גַּאֲוָה y גָּאוֹן (orgullo, altivez). El español ''soberbia'', el francés ''orgueil'' y el alemán ''Übermut'' se alejan del campo semántico de la ira hacia el del orgullo desmedido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122297, 'spa', 'Estallidos o desbordamientos torrenciales de rabia, usados en forma plural para ', 'Estallidos o desbordamientos torrenciales de rabia, usados en forma plural para representar la furia como oleadas o erupciones repetidas y no como un estado único. Solo dos ocurrencias (Job 40:11; Sal 7:6), ambas empleando el plural עֶבְרוֹת para denotar erupciones reiteradas de cólera: ''derrama los desbordamientos de tu ira'' (Job 40:11), ''levántate en los furores de mis adversarios'' (Sal 7:6). El español ''furores'' y el inglés ''outbursts'' captan bien esta imagen de repetición violenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122311, 'spa', 'Hombre o pueblo hebreo (masculino) — la designación gentilicia que identifica a ', 'Hombre o pueblo hebreo (masculino) — la designación gentilicia que identifica a los varones o al pueblo en su conjunto como étnicamente hebreos. Abraham es el primero llamado הָעִבְרִי (Gn 14:13), y el término reaparece en boca de egipcios y filisteos para distinguir a los israelitas: José en prisión (Gn 40:15; 41:12), la narrativa del Arca (1 S 4:6, 9) y la ley del siervo hebreo (Éx 21:2; Dt 15:12). El español ''hebreo/hebreos'' mantiene la distinción con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122316, 'spa', 'Mujer o mujeres hebreas (femenino) — la forma específicamente femenina del genti', 'Mujer o mujeres hebreas (femenino) — la forma específicamente femenina del gentilicio, usada para designar a las mujeres de etnia hebrea. Aparece casi exclusivamente en la narrativa del nacimiento en Éxodo: las parteras hebreas Sifrá y Puá (Éx 1:15-16, 19), la hermana de Moisés ofreciendo buscar una nodriza hebrea (Éx 2:7) y la ley deuteronómica que extiende explícitamente los derechos de manumisión a la mujer hebrea (Dt 15:12). El español ''hebrea/hebreas'' preserva la marca de género.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122322, 'spa', 'Levita merarita', 'Ibrí el levita, registrado en 1 Crónicas 24:27 entre los descendientes de Merari en las divisiones sacerdotales. Su identidad con la palabra ''hebreo'' ha llevado a algunos a considerarlo un problema textual, aunque puede ser simplemente un nombre propio derivado del gentilicio. La variación en los testimonios griegos (Abai, Obdi, Abaria) sugiere incertidumbre antigua sobre la lectura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122323, 'spa', 'Región montañosa moabita', 'Distrito montañoso al noroeste de Moab, al noreste del mar Muerto, que abarca el monte Nebo, donde Moisés subió a contemplar la Tierra Prometida (Nm 27:12; Dt 32:49). El nombre significa ''las regiones de más allá'', y la LXX lo traduce como τὸ πέραν. En Jeremías 22:20 aparece en una invocación poética al lamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122324, 'spa', 'Ciudad de Aser', 'Ebrón, listada entre las ciudades de Aser en Josué 19:28, aunque la evidencia textual sugiere leer ''Abdón'' en su lugar. Las versiones griegas la transcriben como Elbón, Acrán u otras formas similares, revelando incertidumbre temprana. BDB señala que ''probablemente'' debe leerse como Abdón, ciudad levítica asignada a Aser en otros pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122326, 'spa', 'Marchitamiento de granos', 'El marchitamiento de los granos bajo la sequía en Joel 1:17, donde el profeta describe la catástrofe agrícola. «Los granos se marchitan bajo los terrones, los graneros están desolados, los almacenes derruidos»: el verbo retrata vívidamente semillas resecas que nunca germinaron, contraídas y colapsadas en el suelo árido. La conexión con la raíz árabe que significa «contraer» o «fruncir» capta esta imagen de deterioro total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122327, 'spa', 'Tramar corrupción', 'El entrelazamiento de intrigas corruptas en Miqueas 7:3, donde los funcionarios conspiran para pervertir la justicia. «El príncipe pide, el juez acepta soborno, el poderoso dicta su deseo, y juntos lo entretejen»: el verbo retrata la conspiración como un oficio artesanal, el entrelazamiento cuidadoso de múltiples hilos de corrupción en una trama unificada. Algunos proponen enmendar la raíz hacia un sentido de «torcer» o «pervertir».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122328, 'spa', 'Frondoso, de follaje denso', 'Adjetivo que significa frondoso, de follaje denso o espeso, con ramas entrelazadas. Levítico 23:40 y Nehemías 8:15 prescriben «árboles frondosos» (עֵץ עָבֹת) para la celebración de Sucot, mientras que Ezequiel 6:13 y 20:28 condenan las prácticas idolátricas «bajo todo árbol frondoso». Las glosas coinciden en «frondoso/leafy/touffu».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122329, 'spa', 'Ramas gruesas entrelazadas o follaje denso de un árbol, referido a la frondosida', 'Ramas gruesas entrelazadas o follaje denso de un árbol, referido a la frondosidad exuberante y la bóveda forestal. Se encuentra exclusivamente en las alegorías proféticas de árboles de Ezequiel: las ramas gruesas de la vid (Ez 19:11) y las frondosas ramas del gran cedro (Ez 31:3, 10, 14). El hilo semántico que une ambos sentidos es la idea raíz de entrelazar — fibras trenzadas en soga o ramas tejidas en dosel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122330, 'spa', 'Cuerdas trenzadas o retorcidas, sogas y ataduras usadas para atar, sujetar, aseg', 'Cuerdas trenzadas o retorcidas, sogas y ataduras usadas para atar, sujetar, asegurar o tirar. Abarca las cuerdas literales del relato de Sansón (Jue 15:13-14; 16:11-12), los cordones ornamentales del pectoral sacerdotal (Éx 28:14, 22-25) y las ataduras figurativas de la opresión o el pecado (Sal 2:3; Is 5:18). Las glosas interlingüísticas convergen: alemán Schnur, francés corde, español cuerdas/cordones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122344, 'spa', 'Codiciar, desear con lujuria', 'Codiciar, tener un deseo desordenado o pasión por alguien: el sentido verbal en Qal perfecto e imperfecto. Las siete apariciones se concentran en Ezequiel 23, la extensa alegoría de Oholá (Samaria) y Oholibá (Jerusalén) como mujeres que ''codiciaron'' a guerreros asirios y babilonios (23:5, 7, 9, 12, 16, 20). La construcción lleva la preposición עַל (''sobre, tras''), marcando el objeto del deseo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122347, 'spa', 'Amantes, concubinos', 'Amantes, concubinos: el participio usado como sustantivo en Jer 4:30, donde el profeta se dirige a Jerusalén personificada: ''tus amantes te desprecian; buscan tu vida.'' Aquí la palabra pasa del acto verbal a las personas mismas. El español ''los amantes'' confirma la lectura nominal. Este uso participial tiende un puente semántico entre la acción del verbo y sus agentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122349, 'spa', 'Pasión lasciva', 'La pasión lujuriosa de Jerusalén personificada en Ezequiel 23:11, donde el profeta acusa a Judá de superar a Samaria en adulterio espiritual. «Se corrompió más que su hermana en su lascivia y en sus fornicaciones»: el término hebreo enfatiza un deseo intenso y degradante. El paralelismo con «fornicaciones» refuerza la imagen de la infidelidad al pacto como traición sexual compulsiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122350, 'spa', 'Torta, pan plano', 'Pan redondo y plano horneado sobre piedras calientes o brasas, elaborado con diversos granos y usado tanto en la hospitalidad cotidiana como en contextos sagrados. En Gn 18:6, Abraham ordena a Sara preparar tortas de flor de harina para los tres visitantes. Éx 12:39 describe las tortas sin levadura horneadas con la masa sacada de Egipto. Nm 11:8 presenta el maná convertido en tortas, y 1 R 19:6 la torta milagrosa de Elías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122358, 'spa', 'Animal bovino joven, usado literalmente para un becerro criado como alimento o s', 'Animal bovino joven, usado literalmente para un becerro criado como alimento o sacrificio (1 S 28:24; Mal 4:2) y figuradamente como ídolo fundido. El becerro de oro en el Sinaí (Éx 32:4-24) y los becerros de Jeroboam en Betel y Dan (1 R 12:28) dominan el uso polémico. El ''tu becerro, oh Samaria'' de Oseas (8:5) y el reino de paz de Isaías (11:6) extienden la imagen en direcciones opuestas: la idolatría condenada y la armonía mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122376, 'spa', 'Redondo, circular', 'De forma redonda o circular, usado como descriptor físico de objetos manufacturados. Las seis apariciones se encuentran en las descripciones del templo y palacio de 1 Reyes 7-10 y 2 Crónicas 4. El mar de fundición se describe como ''redondo en todo su contorno'' (עָגֹל סָבִיב, 1 Re 7:23 = 2 Cr 4:2), los bastidores de las bases tienen aberturas redondas contrastadas explícitamente con las cuadradas (1 Re 7:31, 35), y el trono del rey tiene un respaldo redondeado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122377, 'spa', 'Novilla, vaca joven', 'Vaca joven empleada en sacrificios, legislación y lenguaje figurado. En el ámbito ritual: el sacrificio del pacto de Abraham (Gn 15:9). En la ley: se le quiebra el cuello para expiar un homicidio sin resolver (Dt 21:3-6). En la metáfora: «mi novilla» de Sansón refiriéndose a su esposa (Jue 14:18), Egipto como una hermosa novilla (Jer 46:20) y Efraín como una novilla adiestrada uncida para labores más pesadas (Os 10:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122387, 'spa', 'Carreta o carro — un vehículo con ruedas tirado por animales para transportar pe', 'Carreta o carro — un vehículo con ruedas tirado por animales para transportar personas, bienes u objetos sagrados. Central en el ciclo de José (Gn 45:19, 21, 27; 46:5), donde el faraón provee carretas para la migración a Egipto, y en los relatos del arca (1 S 6:7-14; 2 S 6:3; 1 Cr 13:7). Números 7:3-8 describe carretas cubiertas (''agalot tsav'') donadas para el transporte del Tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122399, 'spa', 'Carreta de trilla o su rueda, usada como implemento agrícola para separar el gra', 'Carreta de trilla o su rueda, usada como implemento agrícola para separar el grano. En Isaías 28:27-28, el profeta distingue la técnica correcta de trilla: el comino no se trilla con la rueda de una carreta, ni se pasa la carreta interminablemente sobre el grano para hacer pan. El contexto especifica claramente la función de la carreta como instrumento de trilla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122401, 'spa', 'Eglon (nombre propio)', 'Nombre propio con dos referentes: (a) Ciudad real cananea en la Sefela (tierras bajas) de Juda, cuyo rey Debir se unio a la coalicion de cinco reyes contra Gabaon (Jos 10:3, 5). Josue capturo y destruyo Eglon durante su campana sur (Jos 10:34-37) y aparece en la lista de asignacion territorial de Juda (Jos 15:39). (b) Rey de Moab que subyugo a Israel dieciocho anos hasta el dramatico asesinato perpetrado por Ehud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122406, 'spa', 'Angustia compasiva', 'La aflicción de Job por los pobres que sufren en Job 30:25, donde protesta su inocencia recordando su compasión. «¿No lloré por el que estaba en angustia? ¿No se entristeció mi alma por el necesitado?»: el verbo enfatiza una angustia interior, no simple lástima, sino un sufrimiento a nivel del alma junto con los afligidos. El paralelismo con «llorar» muestra que se trata de una participación emocional profunda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122407, 'spa', 'Reclusión del matrimonio', 'La reclusión autoimpuesta del matrimonio en Rut 1:13, donde Noemí pregunta retóricamente si Rut y Orfa «se encerrarían para no pertenecer a varón». El verbo retrata un confinamiento voluntario, un abstenerse del matrimonio mientras se espera indefinidamente. El contexto muestra lo absurdo de la situación de Noemí: aunque engendrara hijos esa noche, ¿se recluirían estas jóvenes para esperarlos?');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122408, 'spa', 'perpetuidad, para siempre (futuro) — Perpetuidad orientada al futuro', 'perpetuidad, para siempre (futuro) — Perpetuidad orientada al futuro: ''para siempre, por siempre jamás'', el sentido dominante con 40 ocurrencias. Se encuentra abrumadoramente en la fórmula litúrgica לְעוֹלָם וָעֶד (Éx 15:18; Sal 9:5; 1 Cr 28:9) y en promesas proféticas de reinado y justicia perdurables (Sal 21:7; Pr 12:19; 29:14). La convergencia multilingüe es sólida: español para siempre, francés pour toujours, alemán ewiglich.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122410, 'spa', 'hasta, hacia, tan lejos como — Punto final preposicional', 'hasta, hacia, tan lejos como — Punto final preposicional: ''hasta, hacia, tan lejos como'' — 7 ocurrencias donde עַד funciona espacial o temporalmente para marcar un límite o término. En Nm 24:20 el fin de Amalec es ''hasta la destrucción''; en 2 S 3:28 David declara su inocencia usando una construcción que funciona como marcador de frontera. Francés jusqu''à y alemán bis preservan esta semántica de límite direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122415, 'spa', 'eternidad (título divino) — Eternidad en un título divino', 'eternidad (título divino) — Eternidad en un título divino: el nomen rectum en el compuesto mesiánico אֲבִי עַד, ''Padre de la Eternidad'' (Is 9:5 [esp. 9:6]). Aquí עַד no es ni pasado ni futuro, sino absoluto, nombrando la soberanía temporal ilimitada como atributo del gobernante venidero. Francés éternité y alemán Ewigkeit recurren a su vocabulario más elevado de ''eternidad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122416, 'spa', 'antigüedad, pasado remoto — Pasado remoto, antigüedad', 'antigüedad, pasado remoto — Pasado remoto, antigüedad: ''desde antaño, desde tiempos inmemoriales'' — solo 2 ocurrencias, pero lexicográficamente importantes. En Job 20:4 Zofar pregunta ''desde que el hombre fue puesto sobre la tierra'' (מִנִּי עַד, ''desde antiguo''), y en Hab 3:6 הַרְרֵי עַד describe ''montes antiguos'' que existen desde tiempos primordiales. La misma palabra que normalmente apunta al futuro aquí mira hacia atrás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122420, 'spa', 'eternidad (concepto abstracto) — La eternidad abstracta como atributo divino', 'eternidad (concepto abstracto) — La eternidad abstracta como atributo divino: en Is 57:15 Dios es descrito como שֹׁכֵן עַד, ''el que habita la eternidad'', donde עַד denota tiempo ilimitado como la morada misma de Dios. A diferencia del ''para siempre'' doxológico del sentido 1, aquí no se trata de duración sino del modo de existencia de Dios: la eternidad como un ámbito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122421, 'spa', 'Hasta, hacia, tan lejos como', 'Sentido preposicional central de extensión espacial o temporal: ''hasta, hacia, tan lejos como''. Este uso abrumadoramente dominante (1.238 apariciones) marca límites en ambas dimensiones: ''hasta que vuelvas a la tierra'' (Gn 3:19), ''desde el hombre hasta la bestia'' (Gn 6:7), ''hasta Sidón'' (Gn 10:19). Con waw conjuntiva y sufijos pronominales genera ''y hasta'', ''hacia él'', etc.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122427, 'spa', '¿Hasta cuándo?', 'La construcción interrogativa-lamentativa עַד־מָתַי y עַד־אָנָה: ''¿hasta cuándo? ¿hasta cuándo más?'' — fórmula retórica que expresa impaciencia, protesta o súplica angustiada. Concentrada en los Salmos (4:2; 6:3; 13:1-2) y la literatura profética, es el clamor del justo sufriente ante Dios. El cuádruple ''¿hasta cuándo?'' del Salmo 13 es una de las lamentaciones más intensas de la Escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122429, 'spa', 'Mientras, durante', 'Sentido conjuntivo-temporal: ''mientras, durante, mientras que'', indicando duración simultánea en lugar de un punto final. Eúd escapó ''mientras'' los siervos se demoraban (Jue 3:26), el sacerdote consultaba ''mientras'' el ruido crecía (1 S 14:19) y Job recibe noticias ''mientras'' el mensajero anterior aún habla (Job 1:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122432, 'spa', 'Perpetuidad, siempre', 'Sentido sustantival de ''perpetuidad, eternidad'', donde עַד funciona como sustantivo en vez de preposición. Presente en las frases poéticas לָעַד (''para siempre'') y la intensificada עֲדֵי־עַד (''por siempre jamás'', lit. ''perpetuidad de perpetuidad''). El Salmo 92:7 declara que los impíos prosperan ''para ser destruidos por siempre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122438, 'spa', 'Ni siquiera, incluso', 'Adverbio enfático-escalar: ''incluso, ni siquiera, hasta'', que intensifica una afirmación para incluir un extremo inesperado. En Deuteronomio 2:5 Dios advierte a Israel: ''No os daré de su tierra, ni siquiera (עַד) la pisada de la planta de un pie''. La fuerza escalar empuja ''hasta'' hacia ''ni aun lo mínimo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122439, 'spa', 'Preposición aramea que marca un límite en el tiempo, el espacio o la cantidad, e', 'Preposición aramea que marca un límite en el tiempo, el espacio o la cantidad, equivalente al hebreo עַד. El uso temporal predomina: ''hasta el tiempo del fin'' (Dn 7:26), ''hasta ahora'' (Esd 5:16). También marca cantidad (''hasta cien talentos'', Esd 7:22) y espacio (''hasta aquí'', Dn 7:28). La conjunción compuesta עַד דִּי introduce cláusulas subordinadas temporales (Dn 2:34; 4:30). Todos los idiomas lo vierten con una sola partícula de límite: español ''hasta'', francés ''jusqu''à'', alemán ''bis''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122442, 'spa', 'Presa y botín', 'Las tres apariciones muestran un rango semántico que va desde la presa literal de caza (Benjamín como lobo) hasta el botín militar (Isaías) y la metáfora teológica (el juicio de Yahvé). La evidencia multilingüe revela cierta confusión: algunas versiones lo interpretan como temporal (''hasta''), lo que sugiere complejidad textual en ciertos pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122443, 'spa', 'testigo (persona que testifica) — Testigo como persona', 'testigo (persona que testifica) — Testigo como persona: alguien que ha visto o sabe algo y puede dar cuenta de ello, ya sea en un procedimiento legal, una ceremonia pactual o un tribunal divino. Este sentido dominante (59 ocurrencias) abarca al ''falso testigo'' del noveno mandamiento (Éx 20:16), el requisito de múltiples testigos para una condena (Nm 35:30; Dt 17:6) y la declaración de Labán de que Dios es testigo del pacto de Mizpa (Gn 31:48).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122447, 'spa', 'testigo (evidencia o atestación) — Testigo como evidencia o atestación', 'testigo (evidencia o atestación) — Testigo como evidencia o atestación: un objeto, monumento, cántico o documento que cumple la función probatoria de testificar, a menudo en frases preposicionales que significan ''como testigo'' o ''por testigo''. Con 11 ocurrencias, este sentido aparece cuando Jacob y Labán erigen un montón de piedras ''como testigo'' entre ellos (Gn 31:44, 52), o cuando el cántico de Moisés se escribe ''por testigo'' contra la apostasía futura (Dt 31:19, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122463, 'spa', 'Impureza menstrual metafórica', 'La metáfora de la mancha menstrual en Isaías 64:6, donde el profeta confiesa: «Todas nuestras obras justas son como vestido de menstruación». La imagen es impactante: lo que Israel considera buenas obras resulta, ante la santidad de Dios, tan inmundo como un paño manchado de sangre menstrual. La forma plural intensifica la noción de contaminación. El paralelo con «todos somos inmundos» revela una impureza moral generalizada.');